    """Return the text of base_dir/user_path, or '' if it cannot be read
    or escapes base_dir."""
    full = os.path.join(base_dir, user_path)
    if not os.path.abspath(full).startswith(os.path.abspath(base_dir)):
        return ''
    try:
        with open(full) as f:
            return f.read()
    except OSError:
        return ''
